function buildSiteDetail(
  state: MockState,
  site: MockSite,
): components["schemas"]["SiteDetailResponse"] {
  const project = state.projects.find((p) => p.id === site.project_id);
  const sectionItems = buildSectionListItems(state, site.id);
  return {
    // 🔴 Sozlesmenin 16 alani KAYITTAN yayilir, tek tek yazilmaz: yazma ucuna
    // giren deger GET'ten AYNEN geri gelmelidir. Once tek tek yazilmadigi icin
    // hicbiri donmuyordu ve dort kapinin dordu de yesildi (K-MKD2).
    ...siteContractPayload(site),
    id: site.id, slug: site.slug, code: site.code, name: site.name, status: site.status, address: site.address,
    city: site.city, city_inherited: site.city_inherited, site_manager_name: site.site_manager_name,
    start_date: site.start_date, end_date: site.end_date, delivery_date: site.delivery_date,
    remaining_days: site.remaining_days, section_count: sectionItems.length,
    worker_count: COUNT_PENDING("timesheet"),
    progress_pct: METRIC_PENDING("progress_payments"),
    project: {
      id: project?.id ?? site.project_id,
      // 🔴 UST KAYDIN slug'i da doner: santiye ekrani PROJEYE cikan baglantiyi
      // bundan kurar (`SiteHeroBar`). Tasinmazsa o baglanti UUID'e duserdi ve
      // kullanici slug'li bir URL'den cikinca adres ANLASILMAZ hale gelirdi.
      slug: project?.slug ?? null,
      name: project?.name ?? "",
      city: project?.city ?? null,
      employer_name: project?.employer_name ?? null,
    },
    section_status_counts: {
      planned: sectionItems.filter((s) => s.status === "planned").length,
      active: sectionItems.filter((s) => s.status === "active").length,
      completed: sectionItems.filter((s) => s.status === "completed").length,
    },
    sections: sectionItems,
    total_progress_payment: METRIC_PENDING("progress_payments"),
    contract_amount: METRIC_PENDING("project_costs"),
  };
}

/**
 * `SectionDetailResponse` gövdesi (schema.d.ts) — `GET /sections/{id}`,
 * `POST /sites/{site_id}/sections` VE `PATCH /sections/{id}` AYNI şekli
 * döndürür (tıpkı `buildSiteDetail` gibi tek yerde kurulur). Dört yer
 * tutucu (`progress_pct`/`boq_item_count`/`budget`/`worker_count`) burada
 * üretilir, fikstürde SAKLANMAZ. BLF-F1.4: elle `budget_amount` yanıttan
 * KALKTI — Bölüm Bedeli tek kaynak, türev `budget`.
 */
function buildSectionDetail(
  state: MockState,
  section: MockSection,
): components["schemas"]["SectionDetailResponse"] {
  const boq = sectionBoqTotals(state, section.id);
  return {
    id: section.id,
    slug: section.slug,
    code: section.code,
    name: section.name,
    status: section.status,
    manager_user_id: section.manager_user_id,
    manager_name: section.manager_name,
    start_date: section.start_date,
    end_date: section.end_date,
    sort_order: section.sort_order,
    // Backend `to_section_detail` zarfları `to_section`ten AYNEN devralır —
    // ikiz de aynı türetmeyi kullanır, aksi hâlde LİSTE "3 iş kalemi" derken
    // DETAY aynı bölüm için "—" basardı (ekranın kendi kendini yalanlaması).
    progress_pct: METRIC_PENDING("progress_payments"),
    boq_item_count: COUNT_VALUE(boq.count, "boq"),
    budget: METRIC_VALUE(boq.amount),
    worker_count: COUNT_PENDING("timesheet"),
    site_id: section.site_id,
    section_type: section.section_type,
    description: section.description,
    deputy_manager_user_id: section.deputy_manager_user_id,
    deputy_manager_name: section.deputy_manager_name,
    planned_worker_count: section.planned_worker_count,
    is_draft: section.is_draft,
    depends_on_section_id: section.depends_on_section_id,
    milestones: section.milestones,
    created_at: section.created_at,
    updated_at: section.updated_at,
  };
}

/**
 * F-TKV T6 — `SectionUpdate.milestones` İKİ GÖVDE SEMANTİĞİ (backend
 * `_merge_milestones` emsali): anahtar YOK / `null` = DOKUNMA, `[]` = HEPSİNİ
 * SİL, dolu dizi = birleştir. `id` verilen satır YERİNDE güncellenir,
 * verilmeyen YENİdir. `sort_order` GÖVDEDEN GELMEZ — dizi sırasından atanır.
 * Bilinmeyen/başka bölüme ait `id` sessizce yeni satıra DÖNMEZ, 422 verir.
 */
function mergeMilestones(
  current: MockMilestone[],
  raw: unknown,
  seq: () => string,
): MockMilestone[] | { error: string } {
  if (raw === undefined || raw === null) return current;
  if (!Array.isArray(raw)) return { error: "milestones bir liste olmalıdır" };
  const known = new Set(current.map((m) => m.id));
  const next: MockMilestone[] = [];
  for (const [index, entry] of raw.entries()) {
    const row = entry as Record<string, unknown>;
    const title = typeof row.title === "string" ? row.title.trim() : "";
    const date = typeof row.milestone_date === "string" ? row.milestone_date : "";
    if (!title || !date) return { error: "Milestone icin ad ve tarih zorunludur" };
    const id = typeof row.id === "string" && row.id ? row.id : null;
    if (id !== null && !known.has(id)) {
      return { error: "Bilinmeyen milestone id" };
    }
    next.push({ id: id ?? seq(), title, milestone_date: date, sort_order: index });
  }
  return next;
}

/**
 * `section_type_id` → liste satırı. `undefined`/`null` = tip yok; bilinmeyen id
 * 422 (backend `_assert_section_type_exists`). Tip ADI hep listeden okunur.
 */
function resolveSectionType(
  state: MockState,
  raw: unknown,
): { type: MockSectionType | null } | { error: string } {
  if (raw === undefined || raw === null) return { type: null };
  const found = typeof raw === "string" ? state.sectionTypes.find((type) => type.id === raw) : undefined;
  return found ? { type: found } : { error: "Bölüm tipi bulunamadı" };
}

/**
 * Backend'in çalışma-zamanı doğrulama kuralı — `app/modules/sites/guards.py::
 * validate_section` (P6 §7 spec, OpenAPI'de KODLU DEĞİL). Tutarlılık kuralı
 * taslakta DA uygulanır; zorunluluk kuralları YALNIZ `is_draft: false` iken.
 * BLF-F1.4: `budget_amount` zorunluluğu KALKTI (bedel türevdir). Tip zorunluluğu
 * (F-c) kalır ve PATCH ile yayındaki bölümde tipi boşaltmayı da kapsar.
 */
function validateSectionInput(input: {
  is_draft: boolean;
  section_type: MockSectionType | null;
  manager_user_id: string | null;
  manager_name: string | null;
  start_date: string | null;
  end_date: string | null;
}): string | null {
  if (input.start_date && input.end_date && input.end_date < input.start_date) {
    return "Planlanan bitiş tarihi başlangıçtan önce olamaz.";
  }
  if (input.is_draft) return null;
  if (input.section_type === null) return "Bölüm tipi seçiniz.";
  const hasManager =
    input.manager_user_id !== null || (input.manager_name !== null && input.manager_name.trim() !== "");
  if (!hasManager) return "Bölüm sorumlusu seçiniz.";
  if (input.start_date === null || input.end_date === null) {
    return "Başlangıç ve planlanan bitiş tarihi zorunludur.";
  }
  return null;
}

// --- F-SD T1 · Şantiye Günlüğü fikstürleri --------------------------------
// Satır iskeleti BOQ pozlarından üretilir. Tohumlu kayıtlar (d-1..d-3) eski
// "tüm kalem" iskeletini taşır; YENİ kayıt kural A'dır (`buildDiaryKuralALines`,
// GKS-F1.2b). Kayıtlar mevcut evrene bağlanır: proje p-1, şantiyeler s-1 / s-2.

/**
 * Mock'un günlük→sözleşme köprüsü. Gerçekte köprü BOQ kaleminin sözleşme
 * kalemine bağlanmasıyla kurulur (backend işi); burada açık bir eşleme
 * tablosu tutulur ki "Günlükten Doldur" akışı e2e'de gerçek veriyle
 * çalışsın. Eşlemesi OLMAYAN poz önerilere GİRMEZ ve
 * `skipped_unbridged_count`a sayılır — üst kural: sessizce yutma yok.
 */
const DIARY_BOQ_BRIDGE: Record<string, { employerItemId?: string; subcontractorItemId?: string }> = {
  "bi-3": { employerItemId: "ci-1" }, // C25/30 Beton → Kat Döşemesi C25/30
  "bi-4": { employerItemId: "ci-3" }, // Demir Donatı → Nervürlü Demir
  "bi-5": { subcontractorItemId: "sci-4" }, // Tuğla Duvar → Duvar Örgü İşleri (sc-2)
  "bi-6": { subcontractorItemId: "sci-5" }, // İç Sıva → Sıva İşleri (sc-2)
};

interface MockDiaryLine {
  id: string;
  boq_item_id: string;
  code: string;
  description: string;
  unit: string;
  unit_price: string;
  quantity: string;
  /**
   * PLN-F2.5a · kalem × bölüm yaprağı (B2). YALNIZ EV gün senaryolarının
   * satırlarında TANIMLIDIR (`evLines`); eski iskelet satırları bu alanı
   * TAŞIMAZ ve yanıtları bayt bayt aynı kalır (Temmuz kareleri).
   */
  section_id?: string | null;
  overrun_reason?: string | null;
}
interface MockDiaryWorkerCount {
  id: string;
  trade: string;
  source: "company" | "subcontractor" | "general";
  count: number;
  /** PLN-F2.5a · FİRMA satırı (G10): taşeron kimliği + kişi başı saat. */
  subcontractor_id?: string | null;
  hours?: string | null;
}
interface MockDiaryEntry {
  id: string;
  site_id: string;
  project_id: string;
  entry_date: string;
  section_id: string | null;
  weather: components["schemas"]["Weather"] | null;
  /**
   * PLN-F2.5a · 10'lu hava + min/max/rüzgâr (B2.1). Girilmemişse YOK → `null`.
   * Eski tek sıcaklık alanı CLEAN-B1'de API'den kalktı; backend göçü
   * (b877270195d8) onu min/max'a kopyalamıştı — ikizde max'ı taşıyan eski
   * fikstürler değeri doğrudan `temp_max_c`de tutar.
   */
  temp_min_c?: string | null;
  temp_max_c?: string | null;
  wind_ms?: string | null;
  work_done: string | null;
  chief_note: string | null;
  safety_meeting_held: boolean;
  ppe_checked: boolean;
  has_incident: boolean;
  incident_note: string | null;
  status: "draft" | "submitted";
  submitted_at: string | null;
  /**
   * DET-1.B · gönderen (backend `submitted_by_user_id`): `submitted_at` ile
   * BİRLİKTE yazılır, reopen temizler. Tanımsız = backend'in DET-1.B ÖNCESİ
   * gönderimi (geri doldurma yok) → yanıtta `null`.
   */
  submitted_by?: string | null;
  created_by: string;
  created_at: string;
  updated_at: string;
  lines: MockDiaryLine[];
  worker_counts: MockDiaryWorkerCount[];
  /**
   * PLN-F2.5a · EV gününün kaydı: satırlar İSKELET DEĞİL, gerçek backend
   * gibi yalnız girilen (kalem × bölüm) satırlarıdır ve `PUT lines` TAM
   * DEĞİŞTİRİR (bölüm + aşım gerekçesi korunur). Eski kayıtlar iskelet
   * davranışını AYNEN sürdürür.
   */
  evLines?: boolean;
  /**
   * 🔒 TEST İZOLASYONU (`hiddenFromLists` emsali). Bölüm detayının günlük
   * sekmesi AY SÜZGEÇSİZ listeyi okur (`section-detail-visual.spec.ts:176`
   * notu) — EV senaryo kayıtları oraya girseydi sec-1'in "1 satır" iddiası ve
   * notun metni/yüksekliği değişirdi. Ay süzgeçli liste (günlük ekranı) onları
   * GÖRÜR. GERÇEK backend'de böyle bir dışlama YOKTUR.
   */
  hiddenFromUnfilteredList?: boolean;
}

const ALL_BOQ_ITEMS = BOQ_FIXTURE.flatMap((g) => g.items);

/** GKS-F1.2b · kural A girdisi: kalem kimliği + kota. */
export interface DiarySkeletonItem {
  readonly id: string;
  readonly quantity: number;
}
/** GKS-F1.2b · kural A çıktısı: (kalem, bölüm | Bölümsüz) + planlı. */
export interface DiarySkeletonKey {
  readonly itemId: string;
  readonly sectionId: string | null;
  readonly planned: number;
}
/**
 * GKS-F1.2b · günlük satır İSKELETİNİN saf kuralı (backend `site_diary/skeleton.py`
 * `skeleton_keys` ikizi, CEO kararı 2026-10-01 · kural A). Önizleme (GET skeleton) ve
 * POST iskeleti AYNI fonksiyonu çağırır.
 *
 *  · BÖLÜM SEÇİLİ: yalnız o bölüme tahsisli kalemler; satır bölümü = o bölüm, planlı = pay;
 *    Bölümsüz YOK.
 *  · BÖLÜM SEÇİLİ DEĞİL: tahsissiz ya da KISMEN tahsisli kalem → tek Bölümsüz satır
 *    (planlı = kota − Σpay); TAMAMEN tahsisli kalem (Σpay ≥ kota) → Bölümsüz YOK, tahsisli
 *    olduğu HER bölüm için bir satır (planlı = pay). Kısmen tahsislinin bölüm satırları AÇILMAZ.
 *  · Sıra: girdi kalem sırası; bir kalemin bölüm satırları bölüm sırasıyla (eşitlikte kimlik).
 */
export function diarySkeletonKeys(
  items: readonly DiarySkeletonItem[],
  allocations: Readonly<Record<string, Readonly<Record<string, number>>>>,
  sectionId: string | null,
  sectionOrder: Readonly<Record<string, number>> = {},
): DiarySkeletonKey[] {
  return items.flatMap((item): DiarySkeletonKey[] => {
    const shares = allocations[item.id] ?? {};
    const sectionIds = Object.keys(shares);
    if (sectionId !== null) {
      return shares[sectionId] === undefined ? [] : [{ itemId: item.id, sectionId, planned: shares[sectionId] }];
    }
    const allocated = sectionIds.reduce((sum, id) => sum + shares[id], 0);
    if (sectionIds.length === 0 || allocated < item.quantity) {
      return [{ itemId: item.id, sectionId: null, planned: Math.max(item.quantity - allocated, 0) }];
    }
    return [...sectionIds]
      .sort((left, right) => (sectionOrder[left] ?? 0) - (sectionOrder[right] ?? 0) || left.localeCompare(right))
      .map((id) => ({ itemId: item.id, sectionId: id, planned: shares[id] }));
  });
}

/** Yeni kaydın satır iskeleti: TÜM BOQ pozları, miktar sıfır. */
function buildDiaryLineSkeleton(entryId: string, quantities: Record<string, number> = {}): MockDiaryLine[] {
  return ALL_BOQ_ITEMS.map((item) => ({
    id: `${entryId}-l-${item.id}`,
    boq_item_id: item.id,
    code: item.code,
    description: item.description,
    unit: item.unit,
    unit_price: item.unit_price,
    quantity: qty3(quantities[item.id] ?? 0),
  }));
}

/**
 * GKS-F1.2b · kural A iskeleti (POST + önizleme ORTAK): kalem × bölüm yaprakları, miktar 0.
 * Kota/tahsis `BOQ_FIXTURE`dan (kayıtlı satırın planlısı `diaryLeafPlanned` ile AYNI kaynak).
 * `entryId` yalnız satır kimliği içindir; önizleme kimliksizdir.
 */
function buildDiaryKuralALines(state: MockState, siteId: string, sectionId: string | null, entryId: string): MockDiaryLine[] {
  const allocations = Object.fromEntries(
    ALL_BOQ_ITEMS.map((item) => [
      item.id,
      Object.fromEntries(Object.entries(item.allocations ?? {}).map(([id, quantity]) => [id, Number(quantity)])),
    ]),
  );
  const sectionOrder = Object.fromEntries(
    state.sections.filter((section) => section.site_id === siteId).map((section) => [section.id, section.sort_order]),
  );
  const keys = diarySkeletonKeys(
    ALL_BOQ_ITEMS.map((item) => ({ id: item.id, quantity: Number(item.quantity) })),
    allocations,
    sectionId,
    sectionOrder,
  );
  return keys.flatMap((key) => evDiaryLines(entryId, [[key.itemId, key.sectionId, 0]]));
}

/** `site_diary/guards.py` metinleri — BİREBİR. */
const DIARY_LINE_SECTION_MISMATCH = "Satırdaki bölüm bu şantiyeye ait değil";
const DIARY_LINE_SECTION_NOT_ALLOCATED =
  "Kalemin bu bölüme tahsisi yok; miktarı Bölümsüz satıra yazın ya da önce BOQ'da tahsis edin";
const DIARY_LINE_ITEM_MISMATCH = "Seçilen poz bu şantiyenin BOQ'suna ait değil";
const DIARY_DUPLICATE_LINE = "Aynı poz (aynı bölümle) gövdede birden fazla kez gönderildi";

/**
 * GKS-F1.2b · `POST /diary` gövdesindeki `lines[]` — backend `lines.merge_lines` ikizi:
 * iskeletle BİRLEŞTİRİR (SİLME YOK). Gövde miktarı/gerekçesi iskelet satırının üstüne yazar,
 * iskelette olmayan geçerli satır sona eklenir. Önce TÜM doğrulama (gövde-içi çift 409 → poz
 * 422 → bölüm 422 → yeni bölümlü satırın tahsisi 422), sonra uygulama. `lines` iskeletin
 * YENİ bir kopyasıdır, girdi değişmez. Hata → `{ status, body }`.
 *
 * `zeroUnmatched` (non-EV `PUT …/lines`): gövdede geçmeyen MEVCUT satır silinmez, miktarı 0'a
 * çekilir (bu ikizin "sıfırlanır" semantiği). Bölüm taşımayan eski tohum satırı (`section_id`
 * tanımsız) bölümsüz yaprak sayılır ve `overrun_reason` ALMAZ — eski yolla bayt bayt aynı kalır.
 */
function mergeDiaryLines(
  skeleton: readonly MockDiaryLine[],
  state: MockState,
  siteId: string,
  entryId: string,
  rawLines: readonly Record<string, unknown>[],
  zeroUnmatched = false,
): { lines: MockDiaryLine[] } | { status: number; body: unknown } {
  const inputs = rawLines.map((raw) => ({
    itemId: String(raw.boq_item_id),
    sectionId: typeof raw.section_id === "string" ? raw.section_id : null,
    quantity: Number(raw.quantity ?? 0),
    overrunReason: typeof raw.overrun_reason === "string" && raw.overrun_reason.trim() !== "" ? raw.overrun_reason : null,
  }));
  const keyOf = (itemId: string, sectionId: string | null): string => `${itemId}:${sectionId ?? "none"}`;
  const keys = inputs.map((input) => keyOf(input.itemId, input.sectionId));
  if (new Set(keys).size !== keys.length) return { status: 409, body: { detail: DIARY_DUPLICATE_LINE } };
  if (inputs.some((input) => !ALL_BOQ_ITEMS.some((item) => item.id === input.itemId))) {
    return { status: 422, body: { detail: DIARY_LINE_ITEM_MISMATCH } };
  }
  if (inputs.some((input) => !diarySectionBelongsToSite(state, input.sectionId, siteId))) {
    return { status: 422, body: { detail: DIARY_LINE_SECTION_MISMATCH } };
  }
  const existing = new Set(skeleton.map((line) => keyOf(line.boq_item_id, line.section_id ?? null)));
  const unallocated = inputs.some(
    (input, index) =>
      input.sectionId !== null && !existing.has(keys[index]) && diaryLeafPlanned(input.itemId, input.sectionId) === null,
  );
  if (unallocated) return { status: 422, body: { detail: DIARY_LINE_SECTION_NOT_ALLOCATED } };

  const byKey = new Map(inputs.map((input, index) => [keys[index], input] as const));
  const merged = skeleton.map((line) => {
    const input = byKey.get(keyOf(line.boq_item_id, line.section_id ?? null));
    if (input === undefined) return zeroUnmatched ? { ...line, quantity: qty3(0) } : line;
    const written = { ...line, quantity: qty3(input.quantity) };
    return line.section_id === undefined ? written : { ...written, overrun_reason: input.overrunReason };
  });
  const added = inputs
    .filter((_, index) => !existing.has(keys[index]))
    .map((input) => ({
      ...evDiaryLines(entryId, [[input.itemId, input.sectionId, input.quantity]])[0],
      overrun_reason: input.overrunReason,
    }));
  return { lines: [...merged, ...added] };
}

/**
 * GKS-F1.2b · kümülatifin kapsamı: AYNI şantiyede `uptoDate`e KADAR girilmiş günlükler.
 * Kayıtlı satır günün kendisini DAHİL sayar (`<=`); kaydedilmemiş önizleme satırı günün
 * mevcut kaydını SAYMAZ (`<`, backend `cumulative_quantities_before`) — kendi miktarı 0'dır.
 */
function diaryEntriesUpTo(state: MockState, siteId: string, uptoDate: string, includeSameDate: boolean): MockDiaryEntry[] {
  return state.diaryEntries.filter(
    (e) => e.site_id === siteId && (includeSameDate ? e.entry_date <= uptoDate : e.entry_date < uptoDate),
  );
}

/**
 * Kayıtlı satır ile önizleme satırının ORTAK türev alanları (`id` hariç) — backend
 * `read.line_fields` ikizi; tek hesap, ikinci kopya YOK. Kümülatif: AYNI şantiye, AYNI poz,
 * `uptoDate`e kadar; ekran bu türevi hesaplamaz, yanıttan okur.
 */
function buildDiaryLineFields(
  state: MockState,
  siteId: string,
  entryDate: string,
  line: MockDiaryLine,
  includeSameDate = true,
): Omit<components["schemas"]["SiteDiaryLineRead"], "id"> {
  const cumulative = diaryEntriesUpTo(state, siteId, entryDate, includeSameDate)
    .flatMap((e) => e.lines.filter((l) => l.boq_item_id === line.boq_item_id))
    .reduce((sum, l) => sum + Number(l.quantity), 0);
  return {
    boq_item_id: line.boq_item_id,
    code: line.code,
    description: line.description,
    unit: line.unit,
    unit_price: line.unit_price,
    quantity: line.quantity,
    cumulative_quantity: qty3(cumulative),
    line_amount: money2(Number(line.quantity) * Number(line.unit_price)),
    // DET-1.B · satır bölümünün ANLIK adı; bölümsüz (ya da bölüm taşımayan
    // iskelet) satırda `null` = "Bölümsüz" (backend `DetailContext.section_name`).
    section_name: diarySectionName(state, line.section_id ?? null),
    ...(line.section_id === undefined ? {} : diaryLeafFields(state, siteId, entryDate, line, includeSameDate)),
  };
}

function buildDiaryLineRead(state: MockState, entry: MockDiaryEntry, line: MockDiaryLine): components["schemas"]["SiteDiaryLineRead"] {
  return { id: line.id, ...buildDiaryLineFields(state, entry.site_id, entry.entry_date, line) };
}

/**
 * PLN-F2.5a · yaprak türevleri (B2): planlı = BOQ tahsisi (bölümsüz yaprakta
 * tahsis DIŞI kalan), yaprak kümülatifi = aynı şantiye · aynı kalem × bölüm ·
 * bu güne KADAR (dahil). YALNIZ `section_id` taşıyan (EV + GKS-F1.2b) satırlarda basılır.
 */
function diaryLeafFields(
  state: MockState,
  siteId: string,
  entryDate: string,
  line: MockDiaryLine,
  includeSameDate: boolean,
): Pick<
  components["schemas"]["SiteDiaryLineRead"],
  "section_id" | "overrun_reason" | "planned_quantity" | "leaf_cumulative_quantity" | "remaining_quantity"
> {
  const sectionId = line.section_id ?? null;
  const cumulative = diaryEntriesUpTo(state, siteId, entryDate, includeSameDate)
    .flatMap((e) => e.lines.filter((l) => l.boq_item_id === line.boq_item_id && (l.section_id ?? null) === sectionId))
    .reduce((sum, l) => sum + Number(l.quantity), 0);
  const planned = diaryLeafPlanned(line.boq_item_id, sectionId);
  return {
    section_id: sectionId,
    overrun_reason: line.overrun_reason ?? null,
    planned_quantity: planned === null ? null : qty3(planned),
    leaf_cumulative_quantity: qty3(cumulative),
    remaining_quantity: planned === null ? null : qty3(planned - cumulative),
  };
}

/** Yaprağın planlı miktarı: bölüm → tahsis; bölümsüz → tahsis dışı kalan. */
function diaryLeafPlanned(boqItemId: string, sectionId: string | null): number | null {
  const item = ALL_BOQ_ITEMS.find((candidate) => candidate.id === boqItemId);
  if (item === undefined) return null;
  const allocations = item.allocations ?? {};
  if (sectionId !== null) return allocations[sectionId] === undefined ? null : Number(allocations[sectionId]);
  const allocated = Object.values(allocations).reduce((sum, qty) => sum + Number(qty), 0);
  return Number(item.quantity) - allocated;
}

function diaryLinesTotal(lines: readonly MockDiaryLine[]): number {
  return lines.reduce((sum, l) => sum + Number(l.quantity) * Number(l.unit_price), 0);
}

function diaryWorkerTotal(entry: MockDiaryEntry): number {
  return entry.worker_counts.reduce((sum, w) => sum + w.count, 0);
}

// --- DET-1.B · salt okunur detay BAĞLAMI (backend `site_diary/detail_context.py`) ---

/** Backend `guards.SECTION_MISMATCH` — BİREBİR (liste süzgeci + detay bağlamı 422'si). */
const DIARY_SECTION_MISMATCH = "Seçilen bölüm bu şantiyeye ait değil";

/** `repository.section_names` ikizi — ANLIK ad; `null` kimlik ya da bulunamayan bölüm → `null`. */
function diarySectionName(state: MockState, sectionId: string | null): string | null {
  if (sectionId === null) return null;
  return state.sections.find((section) => section.id === sectionId)?.name ?? null;
}

/** `repository.user_names` ikizi (`User.full_name`). */
function diaryUserName(state: MockState, userId: string | null): string | null {
  if (userId === null) return null;
  return state.users.find((user) => user.id === userId)?.full_name ?? null;
}

/** `repository.subcontractor_names` ikizi — firmasız satırda `null`. */
function diarySubcontractorName(state: MockState, subcontractorId: string | null): string | null {
  if (subcontractorId === null) return null;
  return state.subcontractors.find((sub) => sub.id === subcontractorId)?.name ?? null;
}

/**
 * `service.validate_section` ikizi: `null` = süzgeç/bağlam yok (geçer); var
 * olmayan ya da BAŞKA şantiyenin bölümü AYNI 422'yi alır → `false`.
 */
function diarySectionBelongsToSite(state: MockState, sectionId: string | null, siteId: string): boolean {
  if (sectionId === null) return true;
  return state.sections.some((section) => section.id === sectionId && section.site_id === siteId);
}

/**
 * DET-1.B KURAL A'nın TEK kopyası (`repository.section_conditions` ikizi) —
 * liste, sayaç ve önceki/sonraki AYNI yüklemi okur. Bölümün günlüğü = başlığı
 * bu bölüm olan gün ∪ bu bölüme MİKTAR SATIRI yazılmış gün (`EXISTS`: kayıt
 * bir kez). Bölüm taşımayan iskelet satırı (`section_id` tanımsız) bölümsüzdür.
 * `null` = süzgeç yok.
 */
function diaryEntryInSection(entry: MockDiaryEntry, sectionId: string | null): boolean {
  if (sectionId === null) return true;
  return entry.section_id === sectionId || entry.lines.some((line) => (line.section_id ?? null) === sectionId);
}

/**
 * `repository.neighbours` ikizi: aynı şantiyede bu günden hemen ÖNCEKİ /
 * SONRAKİ kayıt (gün başına tek kayıt → tarih sırası TAM sıra). Bölüm bağlamı
 * verilirse Kural A kümesinde. 🔴 `hiddenFromUnfilteredList` BURADA UYGULANMAZ:
 * o bayrak yalnız ay süzgeçsiz LİSTENİN test izolasyonudur; gerçek backend'in
 * komşu sorgusunda böyle bir dışlama yoktur.
 */
function diaryNeighbours(
  state: MockState,
  entry: MockDiaryEntry,
  sectionId: string | null,
): { prev: MockDiaryEntry | null; next: MockDiaryEntry | null } {
  const pool = state.diaryEntries.filter(
    (candidate) => candidate.site_id === entry.site_id && diaryEntryInSection(candidate, sectionId),
  );
  const prev = pool
    .filter((candidate) => candidate.entry_date < entry.entry_date)
    .reduce<MockDiaryEntry | null>((best, c) => (best === null || c.entry_date > best.entry_date ? c : best), null);
  const next = pool
    .filter((candidate) => candidate.entry_date > entry.entry_date)
    .reduce<MockDiaryEntry | null>((best, c) => (best === null || c.entry_date < best.entry_date ? c : best), null);
  return { prev, next };
}

/**
 * DET-1.B · detay yanıtına eklenen 12 alan. Gün kilidi EV gün kilidinden
 * (`evDayLocks` ← `evLockState`, TEK kaynak; backend `day_hooks.day_locks`)
 * türer — puantaj haftası ve EV gün görünümüyle aynı kaynak.
 */
function buildDiaryDetailContext(
  state: MockState,
  evState: EvState,
  entry: MockDiaryEntry,
  sectionContext: string | null,
): Pick<
  components["schemas"]["SiteDiaryEntryDetail"],
  | "site_name" | "project_name" | "section_name" | "created_by_name" | "submitted_by" | "submitted_by_name"
  | "locked" | "lock_report_date" | "prev_id" | "prev_entry_date" | "next_id" | "next_entry_date"
> {
  const site = state.sites.find((candidate) => candidate.id === entry.site_id);
  const project = state.projects.find((candidate) => candidate.id === entry.project_id);
  if (site === undefined || project === undefined) {
    throw new Error(`günlük ${entry.id}: şantiye/proje fikstürü yok (${entry.site_id}/${entry.project_id})`);
  }
  const locks = evDayLocks(evState, entry.site_id, [entry.entry_date]);
  const { prev, next } = diaryNeighbours(state, entry, sectionContext);
  const submittedBy = entry.submitted_by ?? null;
  return {
    site_name: site.name,
    project_name: project.name,
    section_name: diarySectionName(state, entry.section_id),
    created_by_name: diaryUserName(state, entry.created_by),
    submitted_by: submittedBy,
    submitted_by_name: diaryUserName(state, submittedBy),
    locked: locks.length > 0,
    lock_report_date: locks[0]?.report_date ?? null,
    prev_id: prev?.id ?? null,
    prev_entry_date: prev?.entry_date ?? null,
    next_id: next?.id ?? null,
    next_entry_date: next?.entry_date ?? null,
  };
}

/**
 * `sectionContext` YALNIZ önceki/sonraki bağlamıdır (`GET /diary/{id}?section_id=`);
 * yazma uçları vermez (backend `build_detail` → şantiye bağlamı).
 */
function buildDiaryEntryDetail(
  state: MockState,
  evState: EvState,
  entry: MockDiaryEntry,
  sectionContext: string | null = null,
): components["schemas"]["SiteDiaryEntryDetail"] {
  return {
    id: entry.id,
    site_id: entry.site_id,
    project_id: entry.project_id,
    entry_date: entry.entry_date,
    section_id: entry.section_id,
    weather: entry.weather,
    temp_min_c: entry.temp_min_c ?? null,
    temp_max_c: entry.temp_max_c ?? null,
    wind_ms: entry.wind_ms ?? null,
    work_done: entry.work_done,
    chief_note: entry.chief_note,
    safety_meeting_held: entry.safety_meeting_held,
    ppe_checked: entry.ppe_checked,
    has_incident: entry.has_incident,
    incident_note: entry.incident_note,
    status: entry.status,
    submitted_at: entry.submitted_at,
    created_by: entry.created_by,
    created_at: entry.created_at,
    updated_at: entry.updated_at,
    ...buildDiaryDetailContext(state, evState, entry, sectionContext),
    lines: entry.lines.map((l) => buildDiaryLineRead(state, entry, l)),
    worker_counts: entry.worker_counts.map((row) => ({
      ...row,
      subcontractor_name: diarySubcontractorName(state, row.subcontractor_id ?? null),
    })),
    lines_total: money2(diaryLinesTotal(entry.lines)),
    worker_total: diaryWorkerTotal(entry),
    dropped_orphan_count: 0,
    // EV-BORC-2 · puantajdan TÜRER (gerçek backend `site_diary/read.py:227`);
    // puantajı olmayan gün boş liste (boş hâl).
    own_crew_from_timesheet: evOwnCrewFromTimesheet(entry.site_id, entry.entry_date),
  };
}

/**
 * DET-1.B ek (backend#130) · liste öğesi: `section_name` = başlık bölümünün adı
 * (başlıksız → null) · `section_line_count` = YALNIZ `?section_id=` verilince o
 * bölüme düşen miktar satırı sayısı (backend `read.section_line_count`), süzgeçsiz null.
 */
function buildDiaryEntryListItem(
  state: MockState,
  entry: MockDiaryEntry,
  sectionFilter: string | null,
): components["schemas"]["SiteDiaryEntryListItem"] {
  return {
    id: entry.id,
    site_id: entry.site_id,
    project_id: entry.project_id,
    entry_date: entry.entry_date,
    section_id: entry.section_id,
    weather: entry.weather,
    has_incident: entry.has_incident,
    status: entry.status,
    worker_total: diaryWorkerTotal(entry),
    lines_total: money2(diaryLinesTotal(entry.lines)),
    created_by: entry.created_by,
    created_at: entry.created_at,
    section_name: diarySectionName(state, entry.section_id),
    section_line_count:
      sectionFilter === null ? null : entry.lines.filter((line) => line.section_id === sectionFilter).length,
  };
}

/** `YYYY-MM-DD` → yıl/ay; string karşılaştırması yeterli, Date kurulmaz. */
function diaryEntryInPeriod(entry: MockDiaryEntry, year: number | null, month: number | null): boolean {
  if (year !== null && Number(entry.entry_date.slice(0, 4)) !== year) return false;
  if (month !== null && Number(entry.entry_date.slice(5, 7)) !== month) return false;
  return true;
}

