  pozNo: string;
  /** TKL-B2.2 · KDV hariç TL birim fiyat (yalnız çekirdek `/catalog/*` ucu döner; KAT ucu ASLA). */
  refPrice: string | null;
  /** Yalnız `refPrice` DEĞİŞİNCE ilerler (ilk atama ve temizleme dahil). */
  priceUpdatedAt: string | null;
